/// The generated surface covers every operation the registry names.
///
/// §27.9 asks for the count and the namespace set to be asserted, so that a
/// partial regeneration fails here rather than shipping 140 of 146.
#[test]
fn generated_surface_matches_the_registry() {
    let expected = expected_surface();
    assert_eq!(
        OPERATIONS.len(),
        expected.len(),
        "generated operation count drifted from management-registry.json"
    );
    for name in &expected {
        assert!(
            OPERATIONS.contains(&name.as_str()),
            "registry operation {name} has no generated method"
        );
    }
}

